/* Помощник для Документов: просьба своими словами → действие. Без сети и внешних сервисов: маленькая обученная
   модель (ресурс «модель», ~1 МБ, общий с Помощником Таблиц) узнаёт, ЧТО сделать, правила достают подробности,
   а делает всё обычный API плагинов. Одна просьба — один шаг «Отменить». */
/* ===== Помощник: понимание просьбы. Признаки — знак в знак как в обучении (work/assistant/features.py),
   модель — хешированные признаки → скрытый слой → намерения; слоты — правилами. Без обращения к приложению:
   этот кусок проверяется и в node. ===== */
const ПМ_D_ПО = 1 << 14;
const ПМ_КАВЫЧКИ = /«[^»]*»|"[^"]*"|“[^”]*”|„[^“”]*[“”]/g;
const ПМ_АДРЕС = /(^|[^a-zа-я0-9])([a-z]{1,3}[0-9]+(?::[a-z]{1,3}[0-9]+)?)(?![a-zа-я0-9])/g;
const ПМ_ЧИСЛО = /[0-9]+(?:[.,][0-9]+)?/g;
function пмНорм(s){
  s = String(s || '').toLowerCase().replace(/ё/g, 'е');
  s = s.replace(ПМ_КАВЫЧКИ, ' кавычки ');
  s = s.replace(ПМ_АДРЕС, (m, a, b) => /^h[1-6]$/.test(b) ? m : a + ' адрес ');
  s = s.replace(ПМ_ЧИСЛО, ' 0 ');
  s = s.replace(/%/g, ' % ');
  s = s.replace(/[^a-zа-я0-9%\- ]/g, ' ');
  s = s.replace(/(^|\s)-+|-+(\s|$)/g, ' ');
  return s.split(/\s+/).filter(Boolean).join(' ');
}
function пмFnv(s){
  let h = 0x811c9dc5;
  for(let i = 0; i < s.length; i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return h >>> 0;
}
function пмПризнаки(s, D){
  D = D || ПМ_D_ПО;
  const н = пмНорм(s), слова = н ? н.split(' ') : [], ключи = [];
  for(let i = 0; i < слова.length; i++){
    const w = слова[i];
    ключи.push('w' + w);
    if(i + 1 < слова.length) ключи.push('b' + w + '_' + слова[i + 1]);
    const ww = '<' + w + '>';
    for(const n of [3, 4, 5]) for(let j = 0; j + n <= ww.length; j++) ключи.push('c' + ww.slice(j, j + n));
  }
  const из = new Map();
  for(const k of ключи){ const x = пмFnv(k) % D; из.set(x, (из.get(x) || 0) + 1); }
  let м = 0; for(const v of из.values()) м += v * v;
  м = Math.sqrt(м) || 1;
  for(const [k, v] of из) из.set(k, v / м);
  return из;
}
/* model.bin: 'PLSA', версия 2, D, H, C, длина имён, имена (JSON), масштабы строк W1 (D×f32), W1 (D×H int8), b1, W2 (H×C), b2 */
function пмМодель(буфер){
  const dv = new DataView(буфер);
  const знак = String.fromCharCode(dv.getUint8(0), dv.getUint8(1), dv.getUint8(2), dv.getUint8(3));
  if(знак !== 'PLSA' || dv.getUint32(4, true) !== 2) throw new Error('Это не модель помощника (или другой её версии)');
  const D = dv.getUint32(8, true), H = dv.getUint32(12, true), C = dv.getUint32(16, true), дл = dv.getUint32(20, true);
  const классы = JSON.parse(new TextDecoder().decode(new Uint8Array(буфер, 24, дл)).trim());
  let o = 24 + дл;
  const s1 = new Float32Array(буфер, o, D); o += D * 4;
  const q1 = new Int8Array(буфер, o, D * H); o += D * H;
  const b1 = new Float32Array(буфер, o, H); o += H * 4;
  const W2 = new Float32Array(буфер, o, H * C); o += H * C * 4;
  const b2 = new Float32Array(буфер, o, C); o += C * 4;
  if(o !== буфер.byteLength || классы.length !== C) throw new Error('Модель помощника повреждена');
  return {D, H, C, классы, s1, q1, b1, W2, b2};
}
/* вероятности намерений; разрешено(имя) — только команды этого приложения */
function пмПредсказать(м, текст, разрешено){
  const x = пмПризнаки(текст, м.D), h = new Float32Array(м.H);
  h.set(м.b1);
  for(const [k, v] of x){ const ш = v * м.s1[k], о = k * м.H; for(let j = 0; j < м.H; j++) h[j] += ш * м.q1[о + j]; }
  for(let j = 0; j < м.H; j++) if(h[j] < 0) h[j] = 0;
  const z = new Float64Array(м.C);
  for(let c = 0; c < м.C; c++){ let s = м.b2[c]; for(let j = 0; j < м.H; j++) s += h[j] * м.W2[j * м.C + c]; z[c] = s; }
  let мах = -Infinity;
  for(let c = 0; c < м.C; c++) if(!разрешено || разрешено(м.классы[c])) мах = Math.max(мах, z[c]);
  let сумма = 0; const p = [];
  for(let c = 0; c < м.C; c++){ const ок = !разрешено || разрешено(м.классы[c]); const e = ок ? Math.exp(z[c] - мах) : 0; сумма += e; p.push({класс: м.классы[c], p: e}); }
  for(const x2 of p) x2.p /= сумма;
  return p.sort((a, b) => b.p - a.p);
}

/* ---------- слоты ---------- */
const пмЛат = s => String(s || '').toLowerCase().replace(/ё/g, 'е');
const ПМ_НЕ_БУКВА = '(?<![а-яa-z])';
/* цвет: корень → цвет букв и мягкая заливка */
const ПМ_ЦВЕТА = [
  ['бордов|вишнев', '#a61e4d', '#f3d9e0', 'бордовый'], ['малинов', '#c2255c', '#fcc2d7', 'малиновый'], ['красн|алый|алым', '#e03131', '#ffc9c9', 'красный'],
  ['розов', '#d6336c', '#ffdeeb', 'розовый'], ['оранжев|рыж|апельсин', '#e8590c', '#ffd8a8', 'оранжевый'], ['лимонн', '#e6b800', '#fff9db', 'лимонный'],
  ['желт', '#f08c00', '#fff3bf', 'жёлтый'], ['золот', '#b08900', '#ffec99', 'золотой'], ['салатов|лаймов', '#66a80f', '#e9fac8', 'салатовый'],
  ['оливков', '#5c940d', '#d8f5a2', 'оливковый'], ['зелен', '#2f9e44', '#d3f9d8', 'зелёный'], ['бирюзов|мятн', '#0c8599', '#c3fae8', 'бирюзовый'],
  ['голуб', '#1c7ed6', '#d0ebff', 'голубой'], ['син', '#1864ab', '#a5d8ff', 'синий'], ['фиолетов|лилов', '#7048e8', '#e5dbff', 'фиолетовый'],
  ['сиренев', '#9c36b5', '#f3d9fa', 'сиреневый'], ['коричнев', '#8b5a2b', '#efe0d0', 'коричневый'], ['сер(?:ый|ым|ая|ой|ую|ого|ом|ые|ыми|ых|ому|енький)', '#868e96', '#e9ecef', 'серый'],
  ['черн', '#000000', '#495057', 'чёрный'], ['бел(?:ый|ым|ая|ой|ую|ого|ом|ые|ыми|ых)', '#ffffff', '#ffffff', 'белый'],
];
const пмСмесь = (hex, к, доля) => { const a = parseInt(hex.slice(1), 16), b = parseInt(к.slice(1), 16);
  const ч = (x, s) => (x >> s) & 255, с = s => Math.round(ч(a, s) * (1 - доля) + ч(b, s) * доля);
  return '#' + [16, 8, 0].map(s => с(s).toString(16).padStart(2, '0')).join(''); };
function пмЦвет(t){
  const s = пмЛат(t);
  const hex = s.match(/#[0-9a-f]{6}\b/);
  if(hex) return {имя: hex[0], текст: hex[0], фон: hex[0]};
  let лучш = null;
  for(const [корень, текст, фон, имя] of ПМ_ЦВЕТА){
    const m = new RegExp(ПМ_НЕ_БУКВА + '((?:светло|темно|ярко|бледно)[- ]?)?(?:' + корень + ')').exec(s);
    if(m && (!лучш || m.index < лучш.i)) лучш = {i: m.index, приставка: (m[1] || '').replace(/[- ]/g, ''), текст, фон, имя};
  }
  if(!лучш) return null;
  let {текст, фон, имя} = лучш;
  if(лучш.приставка === 'темно'){ текст = пмСмесь(текст, '#000000', 0.35); фон = пмСмесь(лучш.текст, '#ffffff', 0.35); имя = 'тёмно-' + имя; }
  else if(лучш.приставка === 'светло' || лучш.приставка === 'бледно'){ текст = пмСмесь(текст, '#ffffff', 0.35); фон = пмСмесь(фон, '#ffffff', 0.45); имя = 'светло-' + имя; }
  else if(лучш.приставка === 'ярко'){ фон = текст; имя = 'ярко-' + имя; }
  return {имя, текст, фон};
}
const ПМ_СЛОВА_ЧИСЕЛ = {ноль: 0, нуля: 0, один: 1, одна: 1, одну: 1, одного: 1, одной: 1, два: 2, две: 2, двух: 2, три: 3, трех: 3, четыре: 4, четырех: 4,
  пять: 5, пяти: 5, шесть: 6, шести: 6, семь: 7, семи: 7, восемь: 8, восьми: 8, девять: 9, девяти: 9, десять: 10, десяти: 10, двенадцать: 12, двенадцати: 12,
  четырнадцать: 14, четырнадцати: 14, шестнадцать: 16, двадцать: 20, двадцати: 20, сто: 100, ста: 100, тысяча: 1000, тысячи: 1000, тысячу: 1000,
  миллион: 1e6, миллиона: 1e6, полтора: 1.5, полторы: 1.5, полуторный: 1.5, полуторным: 1.5, полуторного: 1.5};
/* числа по порядку; адреса клеток и текст в кавычках не считаются */
function пмЧисла(t){
  const s = пмЛат(t).replace(ПМ_КАВЫЧКИ, ' ').replace(ПМ_АДРЕС, '$1 ');
  const out = [], re = new RegExp('-?[0-9]{1,3}(?:[  ][0-9]{3})+(?:[.,][0-9]+)?(?![0-9])|-?[0-9]+(?:[.,][0-9]+)?|' + ПМ_НЕ_БУКВА + '(' + Object.keys(ПМ_СЛОВА_ЧИСЕЛ).join('|') + ')(?![а-я])', 'g');
  let m;
  while((m = re.exec(s))){
    if(m[1]) out.push({ч: ПМ_СЛОВА_ЧИСЕЛ[m[1]], i: m.index, словом: true, хвост: s.slice(m.index + m[0].length, m.index + m[0].length + 16)});
    else out.push({ч: Number(m[0].replace(/[  ]/g, '').replace(',', '.')), i: m.index, хвост: s.slice(m.index + m[0].length, m.index + m[0].length + 16)});
  }
  return out;
}
/* адрес области в просьбе: «A1:D10», «c3» */
function пмАдрес(t){
  const m = /(?:^|[^a-zа-я0-9])([a-z]{1,3}[0-9]+(?::[a-z]{1,3}[0-9]+)?)(?![a-zа-я0-9])/i.exec(String(t || ''));
  return m && !/^h[1-6]$/i.test(m[1]) ? m[1].toUpperCase() : null;
}
function пмВКавычках(t){ const out = []; String(t || '').replace(ПМ_КАВЫЧКИ, m => { out.push(m.slice(1, -1)); return m; }); return out; }
const пмЕсть = (t, re) => re.test(пмЛат(t));
/* «убери», «сними», «без …» — снять оформление, а не поставить */
const пмСнять = t => пмЕсть(t, /(?<![а-я])(убер|убра|сним|снят|отмен|без |выключ|отключ|не нуж|не надо|долой|откреп|разъедин|разморо|сбрось|удали|удалить)/) || пмЕсть(t, /(?<![а-я])не (жирн|курсив|подчерк|зачерк)|верни обычн|обычн[а-я]* (шрифт|вес)/);
const пмПорядокУбыв = t => пмЕсть(t, /убыв|от больш|от высок|от я до а|я-а|сначала (самые )?(больш|дорог|нов|последн|крупн|поздн)|по уменьш|обратн|наибольш|самые (больш|дорог|нов)|наверх|вверх|desc|от новых|z-a/);
function пмФункция(t){
  const s = пмЛат(t);
  if(/средн/.test(s)) return 'СРЗНАЧ';
  if(/максим|наибольш|самое больш|макс(?![а-я])/.test(s)) return 'МАКС';
  if(/миним|наименьш|самое маленьк|мин(?![а-я])/.test(s)) return 'МИН';
  if(/количеств|сколько (строк|записей|значений|штук)|число строк|счет(?![а-я])|посчитай строки/.test(s)) return 'СЧЁТЗ';
  return 'СУММ';
}
function пмСравнение(t){
  const s = пмЛат(t);
  const п = [[/не меньше|не ниже|больше или равно|от(?= [0-9-])|>=|≥/, '>='], [/не больше|не выше|меньше или равно|<=|≤/, '<='], [/не равн|кроме|≠|!=|<>/, '<>'],
    [/больше|выше|свыше|более|превыша|>/, '>'], [/меньше|ниже|менее|до(?= [0-9-])|<|не дотяг/, '<'], [/равн|ровно|=/, '=']];
  for(const [re, оп] of п) if(re.test(s)) return оп;
  return null;
}
const ПМ_ШРИФТЫ = [[/times|таймс|тайм[сз]/, 'Times New Roman'], [/arial|ариал|ариэл/, 'Arial'], [/calibri|калибри/, 'Calibri'], [/pt ?sans|пт ?санс/, 'PT Sans'],
  [/pt ?serif|пт ?сериф/, 'PT Serif'], [/roboto|робото/, 'Roboto'], [/georgia|джорджи/, 'Georgia'], [/verdana|вердан/, 'Verdana'], [/courier|курьер/, 'Courier New'],
  [/tahoma|тахом/, 'Tahoma'], [/open ?sans/, 'Open Sans'], [/liberation ?serif/, 'Liberation Serif'], [/liberation ?sans/, 'Liberation Sans'],
  [/cambria|камбри/, 'Cambria'], [/segoe/, 'Segoe UI'], [/без засеч/, 'Arial'], [/с засечк/, 'Times New Roman'], [/моноширин/, 'Courier New']];
function пмШрифт(t){ const s = пмЛат(t); for(const [re, имя] of ПМ_ШРИФТЫ) if(re.test(s)) return имя; return null; }
function пмКегль(t){
  const ч = пмЧисла(t);
  for(const x of ч) if(/^\s*(pt|пт|кегл|пункт|размер)/.test(x.хвост) && x.ч >= 4 && x.ч <= 200) return x.ч;
  const s = пмЛат(t);
  for(const x of ч){ const до = s.slice(Math.max(0, x.i - 22), x.i); if(/(кегль|размер[а-я]*|шрифт[а-я]*|высот[а-я]*)\s*$/.test(до) && x.ч >= 4 && x.ч <= 200) return x.ч; }
  const ост = ч.filter(x => x.ч >= 6 && x.ч <= 96 && !/^\s*(мм|см|%|строк|столб)/.test(x.хвост));
  return ост.length ? ост[ост.length - 1].ч : null;
}
function пмСтавка(t){
  for(const x of пмЧисла(t)) if([0, 5, 7, 10, 18, 20, 22].includes(x.ч) && (/^\s*(%|процент)/.test(x.хвост) || /ставк|ндс/.test(пмЛат(t).slice(Math.max(0, x.i - 14), x.i)))) return x.ч;
  for(const x of пмЧисла(t)) if(/^\s*(%|процент)/.test(x.хвост)) return x.ч;
  return null;
}
/* точка в конце просьбы — не часть надписи; точка после инициала («И. И.») — часть */
const пмБезТочки = x => { x = String(x).trim(); return /(^|\s)[А-ЯЁA-Z]\.$/.test(x) ? x : x.replace(/[.!]+$/, '').trim(); };
/* надпись для подложки, колонтитула, имя листа: кавычки, после «надпись»/«—», слово капсом */
function пмНадпись(t, слова){
  const к = пмВКавычках(t); if(к.length) return к[0].trim();
  const s = String(t || '').trim();
  let m = /(?:надпись(?:ю)?|текст(?:ом)?|с именем|под названием|с названием|назови(?:те)?(?: его| её)?|именем|слова(?:ми)?)\s*[:—-]?\s+(.+)$/i.exec(s);
  if(m) return пмБезТочки(m[1]);
  m = /\s[—:-]\s*(.+)$/.exec(s); if(m) return пмБезТочки(m[1]);
  const кап = s.match(/(?<![А-ЯЁA-Z])[А-ЯЁA-Z]{3,}(?:\s+[А-ЯЁA-Z]{2,})*(?![А-ЯЁA-Z])/g);
  if(кап) { const x = кап.find(w => !/^(НДС|PDF|DOCX|XLSX|ODT|CSV|ГОСТ|ООО|ИП|АО)$/.test(w)); if(x) return x; }
  for(const w of (слова || [])) if(new RegExp(ПМ_НЕ_БУКВА + w, 'i').test(s)) return w.toUpperCase();
  return null;
}
/* столбец по букве («столбец C», «по B») или по заголовку («по сумме» → «Сумма») */
const ПМ_БУКВЫ_КИР = {'а': 'A', 'б': 'B', 'в': 'B', 'с': 'C', 'ц': 'C', 'д': 'D', 'е': 'E', 'ф': 'F', 'г': 'G', 'х': 'H', 'н': 'H', 'и': 'I', 'к': 'K', 'л': 'L', 'м': 'M'};
const пмНомерСтолбца = б => { let n = 0; for(const ch of б.toUpperCase()) n = n * 26 + ch.charCodeAt(0) - 64; return n - 1; };
const ПМ_СЛУЖЕБНЫЕ = /^(сорт|отсор|упоря|убыв|возра|алфав|сумм|итог|посчи|сгруп|групп|столб|колон|строк|данн|табли|значен|выдел|подсв|больш|меньш|покаж|сдела|каждо|разрез|сначал|снача|диагр|графи|постр|числ|цифр|ячейк|клетк|формат|округ|пожал|отсорт)/;
function пмСтолбцы(t, шапка){
  const s = пмЛат(t), найдено = [];
  const явн = /(?:столб[а-я]*|колонк[а-я]*|графа|графе|по)\s+([a-z]{1,2}|[абвсцдефгхникулм])(?![a-zа-я0-9])/gi;
  let m;
  while((m = явн.exec(s))){ const б = /[a-z]/.test(m[1]) ? m[1] : ПМ_БУКВЫ_КИР[m[1]]; if(б && !(m[1] === 'в' && /^по/.test(m[0]))) найдено.push({абс: пмНомерСтолбца(б), i: m.index + m[0].length - m[1].length}); }
  const слова = []; s.replace(/[а-яa-z]{3,}/g, (w, i) => { слова.push({w, i}); return w; });
  (шапка || []).forEach((h, j) => {
    const hs = пмЛат(h).match(/[а-яa-z0-9]+/g) || [];
    let лучш = 0, где = -1;
    for(const {w, i} of слова){
      const служ = ПМ_СЛУЖЕБНЫЕ.test(w);
      for(const x of hs){
        let k = 0; while(k < w.length && k < x.length && w[k] === x[k]) k++;
        const нужно = Math.max(служ ? 4 : 0, Math.min(x.length, Math.max(3, Math.min(w.length, x.length) - 2)));
        if(k >= нужно && k > лучш){ лучш = k; где = i; }
      }
    }
    if(лучш) найдено.push({отн: j, i: где, сила: лучш});
  });
  return найдено.sort((a, b) => a.i - b.i);
}
function пмФормат(t){
  const s = пмЛат(t);
  if(/pdf|пдф/.test(s)) return 'pdf';
  if(/csv|цсв/.test(s)) return 'csv';
  if(/odt|опен ?док/.test(s)) return 'odt';
  if(/ods/.test(s)) return 'ods';
  if(/txt|текстов|простой текст|\bтекст\b/.test(s)) return 'txt';
  if(/plsx/.test(s)) return 'plsx';
  if(/plsd/.test(s)) return 'plsd';
  if(/xlsx|эксел|excel|xls/.test(s)) return 'xlsx';
  if(/docx|ворд|word|doc/.test(s)) return 'docx';
  return null;
}
/* ---------- шаги: одна просьба — несколько команд ---------- */
/* Описание режется на шаги: по строкам, «;», точке между предложениями, пунктам («1)», «2.», «-», «•»)
   и словам «потом», «затем», «далее», «после этого», «а также», «и ещё». Запятая и союз «и» делят шаг
   только когда он целиком узнаётся неуверенно, а обе половины — уверенно и как разные команды:
   «шапку жирным и курсивом» — два шага, «выдели больше 1000 и меньше 2000 жёлтым» — один.
