function показатьИсторию(){
  if(!история.length){
    панель.поле('ответ', [{текст: 'Напишите, что сделать, и нажмите Enter. Например: ', цвет: СЕРЫЙ},
      {текст: ВТАБЛИЦАХ ? '«залей шапку голубым», «отсортируй по сумме по убыванию», «добавь итоги внизу»' : '«сделай это заголовком», «поля 2 см», «поставь подложку ЧЕРНОВИК»', курсив: true}]);
    return;
  }
  const части = [];
  история.forEach((х, i) => {
    if(i) части.push({текст: '\n\n'});
    части.push({текст: х.текст, жирный: true});
    const и = х.итог || {};
    const цвет = и.ошибка ? КРАСНЫЙ : и.вопрос || и.нет ? СИНИЙ : и.справка ? null : ЗЕЛЁНЫЙ;
    части.push({текст: '\n' + (и.ошибка || и.ответ || ''), цвет: цвет || undefined});
    if(и.намерение && i === 0 && !и.ошибка) части.push({текст: '  (' + НАМЕРЕНИЯ[и.намерение].что + (и.уверенность < 0.999 ? ', уверенность ' + Math.round(и.уверенность * 100) + '%' : '') + ')', цвет: СЕРЫЙ});
    if(и.шагов && i === 0) части.push({текст: '  (шагов: ' + и.шагов + ', выполнено: ' + и.выполнено + ')', цвет: СЕРЫЙ});
  });
  панель.поле('ответ', части);
}

const ОБЩИЕ = {
  справка: async () => ({ответ: справка(), ничего: true}),
  отменить: async () => {
    if(последнее){ const п = последнее; последнее = null; await п.f(); return 'Отменил: ' + п.что; }
    return {ответ: 'Нажмите «Отменить» (Ctrl+Z): каждая просьба помощнику — один шаг отмены, вернётся всё, что она сделала.', ничего: true};
  },
  сохранить: async т => {
    const ф = пмФормат(т);
    if(ф === 'pdf') отказ('В PDF помощник не сохраняет — это делает печать приложения. Сохранить могу в ' + (ВТАБЛИЦАХ ? 'xlsx, csv или plsx' : 'docx, odt, txt или plsd') + '.');
    const можно = ВТАБЛИЦАХ ? ['xlsx', 'csv', 'plsx'] : ['docx', 'odt', 'txt', 'plsd'];
    const формат = можно.includes(ф) ? ф : можно[0];
    const байты = ВТАБЛИЦАХ ? await книга.собрать({формат}) : await документ.собрать(формат);
    const имя = String((ВТАБЛИЦАХ ? '' : документ.имя) || (ВТАБЛИЦАХ ? 'Книга' : 'Документ')).replace(/\.[a-z0-9]{2,5}$/i, '').replace(/[\\/:*?"<>|]/g, ' ').trim() || 'Файл';
    const итог = await файл.выгрузить(имя + '.' + формат, байты);
    return {ответ: итог && итог.сохранено === false ? 'Сохранение отменено' : 'Сохранено: ' + имя + '.' + формат + (ф && ф !== формат ? ' (в ' + ф + ' не умею, взял ' + формат + ')' : ''), ничего: true};
  },
};

function справка(){
  const т = ['Жирный, курсив, подчеркнуть, зачеркнуть («сними жирный»)', 'Цвет текста и заливка: «залей голубым», «буквы красным»',
    'Выравнивание, шрифт и размер: «по центру», «шрифт Arial 12»', 'Регистр, лишние пробелы, «замени «ООО» на «АО»»'];
  return [...т, ...СПРАВКА_ПРИЛ, 'Что не так — «Отменить» (Ctrl+Z): одна просьба — один шаг.'].map(x => '• ' + x).join('\n');
}
const ДЕЛА_Т = {};
/* ======================= Документы ======================= */
/* текст в разметке без тегов: правим только куски между тегами — оформление внутри абзаца остаётся */
function поТексту(html, f){
  return String(html).split(/(<[^>]*>)/).map(ч => ч.startsWith('<') ? ч : эк(f(ч.replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&')))).join('');
}
function гдеКурсор(){
  const в = документ.выделение || {};
  if(!(в.блок >= 0)) отказ('Поставьте курсор в документ (в нужный абзац) или выделите текст.');
  return в;
}
/* выделенное внутри абзаца — правкой разметки самого абзаца: так следующая просьба видит свежий текст
   (замена выделения идёт мимо снимка плагина); выделенное встречается в абзаце не один раз или через теги — заменой выделения */
const разЭк = x => x.replace(/&nbsp;/g, '\u00a0').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
function вВыделенном(в, f){
  const б = документ.блок(в.блок), т = в.текст;
  if(б && т && !/\n/.test(т) && б.текст.split(т).length === 2){
    const куски = String(б.html).split(/(<[^>]*>)/);
    for(let i = 0; i < куски.length; i++){
      if(куски[i].startsWith('<')) continue;
      const сырой = разЭк(куски[i]), k = сырой.indexOf(т);
      if(k < 0) continue;
      куски[i] = эк(сырой.slice(0, k)) + f(т) + эк(сырой.slice(k + т.length));
      документ.правитьБлок(в.блок, {html: куски.join('')});
      return;
    }
  }
  документ.заменитьВыделение(f(т));
}
/* оформить выделенное, а без выделения — весь абзац с курсором */
function обернуть(т, открыть, закрыть, снять, что){
  const в = гдеКурсор();
  if(в.есть && в.текст){
    const б = документ.блок(в.блок);
    if(снять && б && б.текст.trim() === в.текст.trim()) документ.правитьБлок(в.блок, {html: снять(б.html)});
    else вВыделенном(в, x => снять ? эк(x) : открыть + эк(x) + закрыть);
    return что + ' — выделенное (' + (в.текст.length > 30 ? в.текст.slice(0, 30) + '…' : в.текст) + ')';
  }
  const б = документ.блок(в.блок);
  if(!б || !б.текст.trim()) отказ('Абзац пуст: выделите текст или поставьте курсор в абзац с текстом.');
  документ.правитьБлок(в.блок, {html: снять ? снять(б.html) : открыть + б.html + закрыть});
  return что + ' — абзац ' + (в.блок + 1);
}
const снятьТеги = re => h => String(h).replace(re, '');
function абзацем(и, стиль){
  const б = документ.блок(и);
  const тег = б.тег.toLowerCase(), старый = (б.стиль || '').replace(/text-align\s*:[^;]*;?/i, '').trim();
  документ.удалить(и);
  документ.вставить(и, '<' + тег + ' style="' + эк((старый ? старый.replace(/;?$/, ';') : '') + стиль) + '">' + б.html + '</' + тег + '>');
}
const ТИПОГРАФ = s => s.replace(/(^|[\s(\[«„-])"(?=\S)/g, '$1«').replace(/"/g, '»').replace(/(^|[\s(])'(?=\S)([^']*?)'(?=[\s.,;:!?)]|$)/g, '$1«$2»')
  .replace(/ +(-|–|--) +/g, ' — ').replace(/^(-|–|--) /, '— ').replace(/\.\.\./g, '…');
const ДЕЛА_Д = {
  жирный: т => обернуть(т, '<b>', '</b>', пмСнять(т) && снятьТеги(/<\/?(b|strong)(\s[^>]*)?>/gi), пмСнять(т) ? 'Жирный снят' : 'Полужирный'),
  курсив: т => обернуть(т, '<i>', '</i>', пмСнять(т) && снятьТеги(/<\/?(i|em)(\s[^>]*)?>/gi), пмСнять(т) ? 'Курсив снят' : 'Курсив'),
  подчеркнуть: т => обернуть(т, '<u>', '</u>', пмСнять(т) && снятьТеги(/<\/?u(\s[^>]*)?>/gi), пмСнять(т) ? 'Подчёркивание снято' : 'Подчёркивание'),
  зачеркнуть: т => обернуть(т, '<s>', '</s>', пмСнять(т) && снятьТеги(/<\/?(s|strike|del)(\s[^>]*)?>/gi), пмСнять(т) ? 'Зачёркивание снято' : 'Зачёркивание'),
  цвет_текста: т => { const ц = пмЦвет(т); if(!ц && !/обычн|стандарт|верни/.test(пмЛат(т))) отказ('Какой цвет? Например: «текст синим».');
    return ц ? обернуть(т, '<span style="color:' + ц.текст + '">', '</span>', null, 'Цвет текста — ' + ц.имя)
      : обернуть(т, '', '', h => h.replace(/<span style="color:[^"]*">([\s\S]*?)<\/span>/gi, '$1'), 'Цвет текста — обычный'); },
  заливка: т => { const ц = пмЦвет(т);
    if(пмСнять(т) || /без (цвета|заливки|выделения)|прозрачн/.test(пмЛат(т))) return обернуть(т, '', '', h => h.replace(/<span style="background(?:-color)?:[^"]*">([\s\S]*?)<\/span>/gi, '$1').replace(/<\/?mark[^>]*>/gi, ''), 'Выделение цветом снято');
    const цвет = ц || {имя: 'жёлтый', фон: '#fff3bf'};
    return обернуть(т, '<span style="background-color:' + цвет.фон + '">', '</span>', null, 'Выделение цветом — ' + цвет.имя); },
  выравнивание: т => { const в = гдеКурсор(), s = пмЛат(т);
    const к = /ширин/.test(s) ? ['justify', 'по ширине'] : /прав|вправо|справа/.test(s) ? ['right', 'вправо'] : /лев|влево|слева/.test(s) ? ['left', 'влево'] : ['center', 'по центру'];
    абзацем(в.блок, 'text-align:' + к[0]); документ.перейти(в.блок);
    return 'Абзац ' + (в.блок + 1) + ' — ' + к[1]; },
  регистр: т => { const s = пмЛат(т);
    const f = /строчн|маленьк|нижн|lowercase|убер[а-я]* капс|сним[а-я]* капс/.test(s) ? [x => x.toLowerCase(), 'строчными']
      : /каждое слово|кажд[а-я]* слов|имена|фио|первые буквы/.test(s) ? [x => x.toLowerCase().replace(/(^|[\s«"(-])([a-zа-яё])/g, (m, a, b) => a + b.toUpperCase()), 'Каждое Слово С Заглавной']
      : /как в предложении|первую букву|первая буква/.test(s) ? [x => x.toLowerCase().replace(/^(\s*["«(]?)([a-zа-яё])/, (m, a, b) => a + b.toUpperCase()).replace(/([.!?]\s+)([a-zа-яё])/g, (m, a, b) => a + b.toUpperCase()), 'как в предложении']
      : [x => x.toUpperCase(), 'ПРОПИСНЫМИ'];
    const в = гдеКурсор();
    if(в.есть && в.текст){ вВыделенном(в, x => эк(f[0](x))); return 'Выделенное — ' + f[1]; }
    const б = документ.блок(в.блок); документ.правитьБлок(в.блок, {html: поТексту(б.html, f[0])}); return 'Абзац ' + (в.блок + 1) + ' — ' + f[1]; },
  пробелы: () => { let n = 0;
    документ.блоки.forEach((б, i) => { if(б.тег === 'TABLE' || !/ {2,}|^\s|\s$| {2,}/.test(б.текст)) return;
      const h = поТексту(б.html, x => x.replace(/[  ]{2,}/g, ' ')).replace(/^(\s|&nbsp;)+|(\s|&nbsp;)+$/g, '');
      if(h !== б.html){ документ.правитьБлок(i, {html: h}); n++; } });
    return n ? 'Лишние пробелы убраны в абзацах: ' + n : {ответ: 'Лишних пробелов не нашёл', ничего: true}; },
  заменить: т => { const з = пмЗамена(т);
    if(!з || !з.что || з.чем === null) отказ('Что на что заменить? Например: замени «ООО» на «АО».');
    let n = 0, мест = 0; const образец = new RegExp(з.что.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    документ.блоки.forEach((б, i) => { if(!б.текст.includes(з.что)) return;
      const h = поТексту(б.html, x => { const k = (x.match(образец) || []).length; мест += k; return x.replace(образец, з.чем); });
      if(h !== б.html){ документ.правитьБлок(i, {html: h}); n++; } else if(б.текст.includes(з.что)){ мест += б.текст.split(з.что).length - 1; документ.правитьБлок(i, {текст: б.текст.split(з.что).join(з.чем)}); n++; } });
    return n ? '«' + з.что + '» → «' + з.чем + '»: замен ' + мест + ' в абзацах: ' + n : {ответ: '«' + з.что + '» в документе не нашёл', ничего: true}; },
  шрифт: т => { const имя = пмШрифт(т), s = пмЛат(т), ст = документ.стили || {}, об = ст['Обычный'] || {};
    let кегль = пмКегль(т);
    const больше = /увелич|крупн|больше|побольше/.test(s), меньше = /уменьш|мельч|меньше|поменьше/.test(s);
    if(!кегль && (больше || меньше)) кегль = Math.max(6, (об.кегль || 12) + (больше ? 2 : -1));
    if(!имя && !кегль) отказ('Какой шрифт или размер? Например: «шрифт Times New Roman 14».');
    const в = документ.выделение || {};
    if(в.есть && в.текст){ вВыделенном(в, x => '<span style="' + (имя ? 'font-family:' + эк(имя) + ';' : '') + (кегль ? 'font-size:' + кегль + 'pt' : '') + '">' + эк(x) + '</span>');
      return 'Шрифт выделенного: ' + [имя, кегль && кегль + ' пт'].filter(Boolean).join(', '); }
    const о = {}; if(имя) о.шрифт = имя; if(кегль) о.кегль = кегль;
    документ.задатьСтиль('Обычный', о);
    return 'Шрифт основного текста: ' + [имя, кегль && кегль + ' пт'].filter(Boolean).join(', ') + ' (стиль «Обычный»)'; },
  очистить_формат: т => { const в = гдеКурсор();
    if(в.есть && в.текст){ вВыделенном(в, x => эк(x)); return 'Оформление выделенного сброшено'; }
    const б = документ.блок(в.блок);
    документ.удалить(в.блок); документ.вставить(в.блок, '<p>' + эк(б.текст) + '</p>');
    return 'Абзац ' + (в.блок + 1) + ' — простой текст'; },
  заголовок: т => { const в = гдеКурсор(), у = пмУровень(т), б = документ.блок(в.блок);
    if(!б.текст.trim()) отказ('Абзац с курсором пуст.');
    if(б.текст.length > 300) отказ('Абзац длинный (' + б.текст.length + ' знаков) — на заголовок не похож. Поставьте курсор в строку заголовка.');
    документ.правитьБлок(в.блок, {тег: 'H' + у}); return '«' + б.текст.slice(0, 40) + '» — заголовок ' + у; },
  обычный_абзац: т => { const в = гдеКурсор(), б = документ.блок(в.блок); документ.правитьБлок(в.блок, {тег: 'P'}); return '«' + б.текст.slice(0, 40) + '» — обычный абзац'; },
  таблица: т => { const р = пмРазмерТаблицы(т), в = документ.выделение || {};
    const и = в.блок >= 0 ? в.блок + 1 : документ.блоки.length;
    const строки = []; for(let r = 0; r < р.строк; r++) строки.push(Array.from({length: р.столбцов}, () => r === 0 ? '' : ''));
    документ.вставить(и, документ.таблица(строки, {шапка: true}).replace(/<(t[hd])><\/\1>/g, '<$1><br></$1>'));
    документ.перейти(и);
    return 'Таблица: ' + р.столбцов + ' столбц' + (р.столбцов === 1 ? 'а' : 'ов') + ' × ' + р.строк + ' строк' + (р.строк === 1 ? 'а' : '') + ', первая строка — шапка'; },
  поля: т => { const s = пмЛат(т), с = документ.страница || {}, был = с.поля || {верх: 20, низ: 20, лево: 30, право: 15};
    let п = null;
    if(/узк/.test(s)) п = {верх: 12.7, низ: 12.7, лево: 12.7, право: 12.7};
    else if(/широк/.test(s) && !/(уменьш|увелич)/.test(s)) п = {верх: 25.4, низ: 25.4, лево: 50.8, право: 50.8};
    else if(/гост/.test(s)) п = {верх: 20, низ: 20, лево: 20, право: 10};
    else if(/обычн|стандарт|средн|по умолчан/.test(s)) п = {верх: 20, низ: 20, лево: 30, право: 15};
    const ч = пмЧисла(т), мм = пмМм(ч[0]);
    const сторона = /лев/.test(s) ? 'лево' : /прав/.test(s) ? 'право' : /верх|сверху/.test(s) ? 'верх' : /нижн|снизу/.test(s) ? 'низ' : null;
    if(!п && мм){ п = сторона ? {[сторона]: мм} : {верх: мм, низ: мм, лево: мм, право: мм}; }
    if(!п && /уменьш|сузь|меньше/.test(s)) п = {верх: Math.max(5, был.верх - 5), низ: Math.max(5, был.низ - 5), лево: Math.max(5, был.лево - 5), право: Math.max(5, был.право - 5)};
    if(!п && /увелич|расшир|больше/.test(s)) п = {верх: был.верх + 5, низ: был.низ + 5, лево: был.лево + 5, право: был.право + 5};
    if(!п) отказ('Какие поля? Например: «поля 2 см», «узкие поля», «левое поле 3 см», «поля по ГОСТ».');
    for(const k in п) if(п[k] < 0 || п[k] > 100) отказ('Поле ' + Math.round(п[k]) + ' мм — так не бывает; укажите от 0 до 100 мм.');
    документ.задатьСтраницу({поля: п});
    const мм2 = x => (Math.round(x * 10) / 10).toLocaleString('ru-RU');
    return 'Поля, мм: ' + Object.entries(п).map(([k, v]) => k + ' ' + мм2(v)).join(', '); },
  ориентация: т => { const s = пмЛат(т);
    const альб = /альбом|горизонт|боком|поперек|не влез|не помещ|разверн|поверн/.test(s) && !/книжн|вертикал/.test(s);
    документ.задатьСтраницу({ориентация: альб ? 'альбомная' : 'книжная'}); return 'Ориентация: ' + (альб ? 'альбомная' : 'книжная'); },
  интервал: т => { const s = пмЛат(т), об = (документ.стили || {})['Обычный'] || {};
    let и = /полутор|полтора/.test(s) ? 1.5 : /двойн/.test(s) ? 2 : /одинарн/.test(s) ? 1 : null;
    if(и === null){ const ч = пмЧисла(т).find(x => x.ч > 0 && x.ч <= 4); if(ч) и = ч.ч; }
    if(и === null && /реже|свободн|увелич|дальше|пореже/.test(s)) и = Math.round(((об.интервал || 1.15) + 0.25) * 100) / 100;
    if(и === null && /плотн|теснее|уменьш|ближе|почаще|чаще/.test(s)) и = Math.max(1, Math.round(((об.интервал || 1.15) - 0.25) * 100) / 100);
    if(и === null) отказ('Какой интервал? «одинарный», «полуторный», «двойной» или числом: «интервал 1,15».');
    документ.задатьСтиль('Обычный', {интервал: и}); return 'Межстрочный интервал основного текста: ' + String(и).replace('.', ','); },
  отступ: т => { const s = пмЛат(т);
    let мм = пмСнять(т) || /без отступ|без красн/.test(s) ? 0 : пмМм(пмЧисла(т)[0]);
    if(мм === null || мм === undefined) мм = 12.5;
    if(мм > 50) отказ('Отступ ' + мм + ' мм — слишком большой.');
    документ.задатьСтиль('Обычный', {отступПервой: мм});
    return мм ? 'Отступ первой строки: ' + String(мм / 10).replace('.', ',') + ' см' : 'Отступ первой строки убран'; },
  нумерация_страниц: т => { const s = пмЛат(т), к = (документ.страница || {}).колонтитулы || {};
    if(пмСнять(т)){ const о = {}; for(const k of ['верх', 'верхСправа', 'низ', 'низСправа']) if(/\{страница\}/.test(к[k] || '')) о[k] = ''; документ.задатьСтраницу({колонтитулы: о}); return 'Номера страниц убраны'; }
    const текст = /(?<![а-я])из(?![а-я])|всего|n из m/.test(s) ? 'Страница {страница} из {всего}' : '{страница}';
    const верх = /вверх|сверху|верхн/.test(s), справа = /справ|в углу|угол/.test(s);
    const k = (верх ? 'верх' : 'низ') + (справа ? 'Справа' : '');
    const о = {[k]: текст}; for(const x of ['верх', 'верхСправа', 'низ', 'низСправа']) if(x !== k && /\{страница\}/.test(к[x] || '')) о[x] = '';
    документ.задатьСтраницу({колонтитулы: о});
    return 'Номера страниц: ' + (верх ? 'вверху' : 'внизу') + (справа ? ' справа' : ' по центру') + (текст !== '{страница}' ? ', «Страница N из M»' : ''); },
  подложка: т => { const н = пмНадпись(т, ['черновик', 'образец', 'копия', 'конфиденциально', 'секретно', 'проект', 'аннулировано', 'не для распространения']);
    if(!н) отказ('Какую надпись поставить? Например: подложка «ОБРАЗЕЦ».');
    const текст = н.toUpperCase().slice(0, 60), кегль = Math.round(Math.max(24, Math.min(120, 760 / (текст.length * 0.62))));
    документ.подложка({текст, угол: -45, прозрачность: 0.25, кегль, цвет: '#808080'});
    return 'Подложка «' + текст + '» по диагонали на всех страницах'; },
  убрать_подложку: () => { if(!(документ.страница || {}).подложка) return {ответ: 'Подложки и так нет', ничего: true}; документ.подложка(null); return 'Подложка убрана'; },
  колонтитул: т => { const s = пмЛат(т), низ = /нижн|внизу|снизу|подвал/.test(s);
    if(пмСнять(т)){ документ.задатьСтраницу({колонтитулы: низ ? {низ: ''} : /верхн|вверху|сверху/.test(s) ? {верх: ''} : {верх: '', низ: ''}}); return 'Колонтитул убран'; }
    const н = пмНадпись(т);
    if(!н) отказ('Какой текст поставить в колонтитул? Например: верхний колонтитул «ООО Ромашка».');
    документ.задатьСтраницу({колонтитулы: низ ? {низ: н} : {верх: н}});
    return (низ ? 'Нижний' : 'Верхний') + ' колонтитул: «' + н + '»'; },
  оглавление: () => { const бл = документ.блоки, з = [];
    бл.forEach((б, i) => { if(/^H[1-3]$/.test(б.тег) && б.текст.trim()) з.push({у: +б.тег[1], текст: б.текст.trim()}); });
    if(!з.length) отказ('В документе нет заголовков — оглавлению не из чего собраться. Сделайте разделы заголовками: «сделай заголовком».');
    const nav = '<nav class="оглавление" contenteditable="false"><p><b>Оглавление</b></p>' + з.map((x, i) => '<p class="у' + x.у + '"><a data-к="з' + (i + 1) + '">' + эк(x.текст) + '</a><span class="точки"></span><span></span></p>').join('') + '</nav>';
    const было = бл.findIndex(б => б.тег === 'NAV');
    if(было >= 0){ документ.удалить(было); документ.вставить(было, nav); return 'Оглавление обновлено: разделов ' + з.length; }
    const в = документ.выделение || {}, и = в.блок >= 0 ? в.блок : 0;
    документ.вставить(и, nav);
    return 'Оглавление (' + з.length + ' разделов) — перед абзацем ' + (и + 1) + '; номера страниц проставит «Обновить оглавление»'; },
  пустые_абзацы: () => { const бл = документ.блоки; let n = 0;
    for(let i = бл.length - 1; i >= 0; i--){ const б = бл[i]; if(/^(P|DIV|H[1-6])$/.test(б.тег) && !б.текст.replace(/[\s ]/g, '') && !/<(img|table|hr|svg|object)/i.test(б.html)){ документ.удалить(i); n++; } }
    return n ? 'Удалено пустых абзацев: ' + n : {ответ: 'Пустых абзацев нет', ничего: true}; },
  кавычки: () => { let n = 0;
    документ.блоки.forEach((б, i) => { if(б.тег === 'TABLE' || б.тег === 'NAV') return;
      const h = поТексту(б.html, ТИПОГРАФ); if(h !== б.html){ документ.правитьБлок(i, {html: h}); n++; } });
    return n ? 'Кавычки «ёлочками», тире и многоточия — в абзацах: ' + n : {ответ: 'Править нечего: прямых кавычек и дефисов вместо тире нет', ничего: true}; },
};
